TLM.f("Sancti/06-29",{"officium":"SS. Apostolorum Petri et Pauli","rule":["vide C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Acts 12:11"},{"k":"text","la":"Nunc scio vere, quia misit Dóminus Angelum suum: et erípuit me de manu Heródis et de omni exspectatióne plebis Judæórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine; probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Nunc scio vere, quia misit Dóminus Angelum suum: et erípuit me de manu Heródis et de omni exspectatióne plebis Judæórum."}],"Oratio":[{"k":"text","la":"Deus, qui hodiérnam diem Apostolórum tuórum Petri et Pauli martýrio consecrásti: da Ecclésiæ tuæ, eórum in ómnibus sequi præcéptum; per quos religiónis sumpsit exórdium."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 12:1-11"},{"k":"text","la":"In diébus illis: Misit Heródes rex manus, ut afflígeret quosdam de ecclésia. Occidit autem Jacóbum fratrem Joánnis gládio. Videns autem, quia pláceret Judæis, appósuit, ut apprehénderet et Petrum. Erant autem dies azymórum. Quem cum apprehendísset, misit in cárcerem, tradens quátuor quaterniónibus mílitum custodiéndum, volens post Pascha prodúcere eum pópulo. Et Petrus quidem servabátur in cárcere. Orátio autem fiébat sine intermissióne ab ecclésia ad Deum pro eo. Cum autem productúrus eum esset Heródes, in ipsa nocte erat Petrus dórmiens inter duos mílites, vinctus caténis duábus: et custódes ante óstium custodiébant cárcerem. Et ecce, Angelus Dómini ástitit: et lumen refúlsit in habitáculo: percussóque látere Petri, excitávit eum, dicens: Surge velóciter. Et cecidérunt caténæ de mánibus ejus. Dixit autem Angelus ad eum: Præcíngere, et cálcea te cáligas tuas. Et fecit sic. Et dixit illi: Circúmda tibi vestiméntum tuum, et séquere me. Et éxiens sequebátur eum, et nesciébat, quia verum est, quod fiébat per Angelum: existimábat autem se visum vidére. Transeúntes autem primam et secúndam custódiam, venérunt ad portam férream, quæ ducit ad civitátem: quæ ultro apérta est eis. Et exeúntes processérunt vicum unum: et contínuo discéssit Angelus ab eo. Et Petrus ad se revérsus, dixit: Nunc scio vere, quia misit Dóminus Angelum suum, et erípuit me de manu Heródis et de omni exspectatióne plebis Judæórum."}],"Graduale":[{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine."},{"k":"text","la":"Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine, in omni progénie et generatióne."}],"Secreta":[{"k":"text","la":"Hóstias, Dómine, quas nómini tuo sacrándas offérimus, apostólica prosequátur orátio: per quam nos expiári tríbuas et deféndi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quos cœlésti, Dómine, aliménto satiásti: apostólicis intercessiónibus ab omni adversitáte custódi."},{"k":"macro","name":"Per Dominum"}]},"hr":{"43593a16b8d66b45":{"t":"Dj 12, 11, Ps 138, 1-2\n(Dj 12, 11) Sada sigurno znam da je Gospodin poslao svoga anđela i izbavio me iz Herodove ruke i od svega što je očekivao židovski narod. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje ustajanje.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dj 12, 11) Sada sigurno znam da je Gospodin poslao svoga anđela i izbavio me iz Herodove ruke i od svega što je očekivao židovski narod.","kn":"(Dj. Ap, 12, 11). Sad zaista znadem, da je Gospodin poslao anđela svojega, te me izbavio iz ruke Herodove i od svega, što je očekivao židovski narod. (Ps. 133, 1, 2) Gospodine, Ti si me kušao i spopao; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Sad zaista . . .","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"b973e7a4c2bb3482":{"t":"<i>Pomolimo se</i>.\nBože, koji si mučeništvom svojih apostola Petra i Pavla posvetio današnji dan, daj Crkvi svojoj, da u svemu slijedi nauku onih po kojima je primila početak vjere.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si današnji dan posvetio mučeništvom svojih apostola Petra i Pavla, daj Crkvi svojoj, da u svemu slijedi zapovijed onih, od kojih je primila početak vjerovanja, po G. n. I. K.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"f57e65b75000d970":{"t":"Dj 12, 1-11\nČitanje Djela apostolskih. U one dane kralj Herod započe zlostavljati neke članove Crkve. Mačem pogubi Ivanova brata Jakova. Videći da se to sviđa Židovima, dade uhvatiti i Petra, u dane beskvasnih hljebova. Kad ga uhvati, baci ga u tamnicu i preda da ga čuvaju četiri straže, svaka po četiri vojnika. Htio ga je izvesti pred narod poslije Vazma. I dok šu Petra čuvali u tamnici, Crkva se za njega bez prestanka molila Bogu. One noći prije nego ga je Herod namjeravao izvesti, Petar je okovan dvostrukim lancima spavao među dvojicom vojnika, a stražari su pred vratima čuvali tamnicu. I gle, pojavi se anđeo Gospodnji, a svjetlo obasja sobu. Anđeo kucne Petra po rebrima, probudi ga i reče: Ustaj brzo! I lanci mu spadoše s ruku. Anđeo reče: Pripaši se i obuj svoju obuću! On to učini. I zapovjedi mu anđeo; Obuci haljinu i pođi za mnom! Kad je izišao, hodao je za njim i nije znao da je to stvarnost što čini anđeo, jer je držao da je to priviđenje. Prođu prvu i drugu stražu i dođu do željeznih vrata što vode u grad, i ona im se sama otvore. Kad su izašli, prođu jednu ulicu i anđeo iščezne. A Petar dođe k sebi i reče: Sada sigurno znadem da je Gospodin poslao svog anđela i izbavio me iz Herodove ruke i od svega što je očekivao židovski narod.","kn":"Čitanje djela Apostolskih (12, 1-11). U one dane podiže kralj Herod ruke, da muči neke od Crkve. I pogubi mačem Jakova, Ivanova brata. Kad je vidio, da je to drago Zidovima, dade uhvatiti i Petra. A bili su dani beskvasnih hljebova. Kad ga je uhvatio, baci ga u tamnicu i preda, da ga čuvaju četiri straže, u svakoj po četiri vojnika htijući ga po Vazmu izvesti pred narod. Tako su Petra čuvali u tarrtnicl. a Crkva je za njega nepre stana molila Boga. One noći, kad ga je Herod kanio izvesti pred narod, Petar je okovan dvojim verigama spavao među dvojicom vojnika, a stražari su pred vratima čuvali tamnicu. Anđeo Gospodnji pristupi i svijetlo obasja sobu, udari Petra u bok, probudi ga i reče; Ustani brzo! I padoše mu verige s ruku. Tada mu anđeo reče; Pripaši se i obuj se! On učini tako. I zapovjedi mu; Ogrni se svojom haljinom i idi za mnom! I kad je izišaoi, išao je za njim, a nije znao, da je to zbilja, što se događa po anđelu, nego je držao, da ima viđenje. A kad su prošli prvu 1 drugu stražu, dođoše do željeznih vrata, koja vode u grad. I ona im se sama otvoriše. Kad su izišli, prošli su .jednu ulicu, i . odmah odstupi od njega anđeo. A Petar se osvijesti i reče; Sada zaista znam, da je Gospodin poslao svoga anđela, i izbavio me Iz Herodove ruke i od svega, što je očekivao židovski narod.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"e681a81bb44b7de0":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom, spominjat će tvoje ime, Gospodine. Mjesto tvojih otaca rodit će ti se sinovi, zato će te narodi slaviti.\n\nMt 16, 18\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu. <i>Aleluja</i>.","kn":"(Ps. 44, 17, 18). Postavit ćeš ih knezovima po svoj zemlji, sjećat će se imena Tvoga, Gospodine! Mjesto otaca bit će sinovi Tvoji, zato će Te narodi slaviti.\n\nAleluja, aieluja. Ti si Petar i na toj ću stijeni sazidati crkvu svoju, aleluja.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"2eaad8272860ffbe":{"t":"Mt 16, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Kad Isus dođe u krajeve Cezareje Filipove, upita učenike: Što govore ljudi, tko je Sin Čovječji? Oni rekoše: Jedni da je Ivan Krstitelj; drugi da je Ilija; treći opet da je Jeremija ili koji od proroka. Kaže im Isus: A vi, što vi kažete, tko sam ja? Šimun Petar prihvati i reče: Ti si Krist-Pomazanik, Sin Boga živoga. Nato Isus reče njemu: Blago tebi, Šimune, sine Jonin, jer ti to ne objavi tijelo i krv, nego Otac moj, koji je na nebesima. A ja tebi kažem: Ti si Petar-Stijena, i na toj stijeni sazidat ću Crkvu svoju. I vrata paklena neće je nadvladati. A tebi ću dati ključeve kraljevstva nebeskoga. Što god svežeš na zemlji bit će svezano i na nebu. A što god razriješiš na zemlji bit će razriješeno i na nebu.","kn":"t Slijedi sveto evanđelje po Mateju (16, 13-19). U ono vrijeme dođe Isus u krajeve Cezareje Filipove i upita svoje učenike; Sto kažu ljudi; Tko je Sin čovječji? Oni odgovore; Jedni kažu. da je Ivan Krstitelj, drugi Ilija, a drugi da je Jeremija ili kojigod od proroka. Isus ih upita; A vi što kažete; Tko sam ja? Simun Petar odgovori: Ti si Krist, Sin živoga Boga. Isus mu nato reče; Blago tebi, Simune, sine Jonin! Jer ti to nije objavio tijelo i krv, nego moj nebeski Otac. A ja tebi kažem: Ti si Petar, i na toj stijeni sagradit cu svoju Crkvu, i paklena je vrata ne će nadvladati. Tebi ću dati ključeve nebeskoga kraljevstva, 1 štogod svežeš na zemlji, bit će svezano i na ne-’ bu, 1 štogod razriješiš na zemlji, bit će razriješeno i na nebu.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"93805934ca9284fe":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom. Spominjat će tvoje ime, Gospodine, u svakom pokoljenju i naraštaju.","kn":"(Ps. 44, 17). Postavit ćeš ih za knezove po svoj zemlji; spominjat će se imena Tvoga u svakom rodu i potomstvu.","knRef":"Kniewald 1942, str. 514–515 (snimka 258) (OCR)"},"ce8eb4e32cce318e":{"t":"Darove, koje prinosimo na posvetu imenu tvome. Gospodine, neka prati molitva apostola i ona neka nas očisti od grijeha i obrani.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Žrtve, Gospodine, koje prinosimo, da ih ^vetimo imenu Tvojemu, neka prati molitva svetih apostola, koja neka nas i od grijeha očisti i brani, po G. a. I. K.","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"a937e43128eeb79a":{"t":"Mt 16, 18\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu.","kn":"Ti si Petar 1 na toj ću stijeni sazidati crkvu svoju.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"d264ead8fb5621e7":{"t":"<i>Pomolimo se</i>.\nGospodine, po apostolskom zagovoru čuvaj od svake protivštine nas koje si nasitio nebeskom hranom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Po zagovoru svetih apostola čuvaj. Gospodine, od svake protivnosti one, koje si nahranio nebeskom hranom.","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"}}});
